PRAGMA foreign_keys=ON;
CREATE TABLE app_settings(id INTEGER PRIMARY KEY CHECK(id=1),center_name TEXT NOT NULL,phone1 TEXT NOT NULL,phone2 TEXT,address TEXT,logo BLOB,receipt_last INTEGER NOT NULL DEFAULT 0,ending_soon_days INTEGER NOT NULL DEFAULT 7,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE branches(id TEXT PRIMARY KEY,name TEXT NOT NULL,code TEXT NOT NULL UNIQUE,active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE specialties(id TEXT PRIMARY KEY,name TEXT NOT NULL,code TEXT NOT NULL UNIQUE,active INTEGER NOT NULL DEFAULT 1,duration_value INTEGER NOT NULL CHECK(duration_value>0),duration_unit TEXT NOT NULL CHECK(duration_unit IN('day','week','month')),billing_mode TEXT NOT NULL CHECK(billing_mode IN('one_time','monthly')),course_fee INTEGER NOT NULL DEFAULT 0 CHECK(course_fee>=0),monthly_fee INTEGER NOT NULL DEFAULT 0 CHECK(monthly_fee>=0),description TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE specialty_branches(specialty_id TEXT NOT NULL REFERENCES specialties(id),branch_id TEXT NOT NULL REFERENCES branches(id),active INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(specialty_id,branch_id));
CREATE TABLE payment_methods(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE,logo BLOB,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE users(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('ADMIN','REGISTRAR','FINANCE')),branch_id TEXT REFERENCES branches(id),active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE students(id TEXT PRIMARY KEY,full_name TEXT NOT NULL,phone TEXT,secondary_phone TEXT,notes TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_students_name ON students(full_name); CREATE INDEX idx_students_phone ON students(phone);
CREATE TABLE register_sequences(branch_id TEXT NOT NULL REFERENCES branches(id),specialty_id TEXT NOT NULL REFERENCES specialties(id),last_number INTEGER NOT NULL DEFAULT 0 CHECK(last_number>=0),PRIMARY KEY(branch_id,specialty_id));
CREATE TABLE enrollments(id TEXT PRIMARY KEY,student_id TEXT NOT NULL REFERENCES students(id),branch_id TEXT NOT NULL REFERENCES branches(id),specialty_id TEXT NOT NULL REFERENCES specialties(id),register_number INTEGER NOT NULL,start_date TEXT NOT NULL,end_date TEXT NOT NULL,billing_mode_snapshot TEXT NOT NULL,duration_unit_snapshot TEXT NOT NULL,duration_value_snapshot INTEGER NOT NULL,course_fee_snapshot INTEGER NOT NULL,monthly_fee_snapshot INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'active',notes TEXT,created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(branch_id,specialty_id,register_number));
CREATE INDEX idx_enrollments_student ON enrollments(student_id);CREATE INDEX idx_enrollments_dates ON enrollments(start_date,end_date);
CREATE TABLE billing_periods(id TEXT PRIMARY KEY,enrollment_id TEXT NOT NULL REFERENCES enrollments(id),period_number INTEGER NOT NULL,period_start TEXT NOT NULL,period_end TEXT NOT NULL,due_date TEXT NOT NULL,amount_due INTEGER NOT NULL CHECK(amount_due>=0),UNIQUE(enrollment_id,period_number));
CREATE TABLE payments(id TEXT PRIMARY KEY,enrollment_id TEXT NOT NULL REFERENCES enrollments(id),amount INTEGER NOT NULL CHECK(amount>0),payment_method_id TEXT NOT NULL REFERENCES payment_methods(id),paid_at TEXT NOT NULL,description TEXT,created_by TEXT NOT NULL REFERENCES users(id),status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('active','void')),voided_at TEXT,void_reason TEXT,voided_by TEXT REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_payments_date ON payments(paid_at,status);CREATE INDEX idx_payments_enrollment ON payments(enrollment_id,status);
CREATE TABLE payment_allocations(payment_id TEXT NOT NULL REFERENCES payments(id),billing_period_id TEXT NOT NULL REFERENCES billing_periods(id),amount INTEGER NOT NULL CHECK(amount>0),PRIMARY KEY(payment_id,billing_period_id));
CREATE TABLE receipts(id TEXT PRIMARY KEY,receipt_number INTEGER NOT NULL UNIQUE,payment_id TEXT NOT NULL UNIQUE REFERENCES payments(id),enrollment_id TEXT NOT NULL REFERENCES enrollments(id),issued_at TEXT NOT NULL,snapshot_json TEXT NOT NULL);
CREATE TABLE audit_log(id TEXT PRIMARY KEY,actor_id TEXT REFERENCES users(id),action TEXT NOT NULL,entity TEXT NOT NULL,entity_id TEXT,metadata_json TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
